package vn.chitieu.data
import android.content.Context
import androidx.room.Room
import androidx.test.core.app.ApplicationProvider
import androidx.test.ext.junit.runners.AndroidJUnit4
import kotlinx.coroutines.flow.first
import kotlinx.coroutines.test.runTest
import org.junit.Assert.*
import org.junit.Test
import org.junit.runner.RunWith
import vn.chitieu.domain.*
import vn.chitieu.statistics.*
import java.time.LocalDate
@RunWith(AndroidJUnit4::class) class StatisticsDatabaseTest {
 @Test fun aggregatesExcludeUnconfirmedAndFilterWalletAndTimezone()=runTest {val context=ApplicationProvider.getApplicationContext<Context>();val db=Room.inMemoryDatabaseBuilder(context,LedgerDb::class.java).build();try {val p=periodFor("Tháng",LocalDate.of(2026,10,1));val dao=db.dao();dao.save(Entry(id="test-a",amount=3000000000,createdAt=p.from,category="A"));dao.save(Entry(id="test-b",amount=2000000000,createdAt=p.from,wallet="Ngân hàng",kind=Kind.INCOME));Status.entries.filter{it!=Status.CONFIRMED}.forEach {dao.save(Entry(amount=999999999999,createdAt=p.from,status=it))};dao.save(Entry(amount=999999999999,createdAt=p.until));val summary=db.statistics().summary(p.from,p.until,"","").first();assertEquals(3000000000,summary.expense);assertEquals(2000000000,summary.income);assertEquals(2L,summary.count);assertEquals(1L,db.statistics().summary(p.from,p.until,"Tiền mặt","").first().count);assertEquals("2026-10-01",db.statistics().days(p.from,p.until,"","EXPENSE").first().single().label);assertEquals(1,db.statistics().categories(p.from,p.until,"","EXPENSE").first().size);dao.save(Entry(amount=12345,createdAt=p.from,source=Source.QR,recipient="000000",receivingBank="NGUOI NHAN GIA"));assertEquals("NGUOI NHAN GIA",db.statistics().recipients(p.from,p.until,"").first().single().label)}finally{db.close()}}
 @Test fun migration2To3PreservesEntriesAndCreatesIndex()=runTest {val context=ApplicationProvider.getApplicationContext<Context>();val name="test-v3-"+java.util.UUID.randomUUID();try{val initial=Room.databaseBuilder(context,LedgerDb::class.java,name).build();initial.dao().save(Entry(id="preserve",amount=4000000000));initial.openHelper.writableDatabase.apply {execSQL("DROP INDEX index_entries_status_createdAt_kind_wallet_category");execSQL("UPDATE room_master_table SET identity_hash='legacy-v2' WHERE id=42");version=2};initial.close();val upgraded=Room.databaseBuilder(context,LedgerDb::class.java,name).addMigrations(MIGRATION_2_3).build();try{assertEquals(4000000000,upgraded.dao().get("preserve")!!.amount);assertEquals(1L,upgraded.statistics().summary(0,Long.MAX_VALUE,"","").first().count)}finally{upgraded.close()}}finally{context.deleteDatabase(name)}}
 @Test fun pinChangeAndDisableRequireCorrectExistingPin()=runTest {val context=ApplicationProvider.getApplicationContext<Context>();val preferences=Preferences(context);val before=preferences.settings.first();val attempts=context.getSharedPreferences("pin_attempts",0);val saved=attempts.all;attempts.edit().clear().commit();val gate=PinGate(context,preferences);try {val salt="AAECAwQFBgcICQoLDA0ODw==";val old="986qxnMbMmzuHyS3MK9F7gz4EXIuhMjAubUlwLFpHTo=";preferences.pin(salt,old);val settings=preferences.settings.first();assertFalse(gate.change("000000".toCharArray(),"654321".toCharArray(),settings));assertEquals(old,preferences.settings.first().pinHash);assertFalse(gate.disable("000000".toCharArray(),settings));assertTrue(gate.change("123456".toCharArray(),"654321".toCharArray(),settings));val changed=preferences.settings.first();assertTrue(gate.verify("654321".toCharArray(),changed));assertTrue(gate.disable("654321".toCharArray(),changed));assertTrue(preferences.settings.first().pinHash.isBlank());preferences.pin(salt,old);repeat(5){assertFalse(gate.verify("000000".toCharArray(),settings))};assertTrue(PinGate(context,preferences).remaining()>0)}finally{preferences.pin(before.pinSalt,before.pinHash);preferences.flag("biometric",before.biometric);val edit=attempts.edit().clear();saved.forEach{(k,v)->when(v){is Int->edit.putInt(k,v);is Long->edit.putLong(k,v)}};edit.commit()}}
 @Test fun watchingPendingEntryIsNotAffectedByANewerPending()=runTest {val context=ApplicationProvider.getApplicationContext<Context>();val db=Room.inMemoryDatabaseBuilder(context,LedgerDb::class.java).build();try{val dao=db.dao();dao.save(Entry(id="first-pending",amount=100,status=Status.PENDING));dao.save(Entry(id="newer-pending",amount=200,status=Status.PENDING,createdAt=System.currentTimeMillis()+1));assertEquals(Status.PENDING,dao.observeEntryStatus("first-pending").first());Repository(db).confirm("first-pending");assertEquals(Status.CONFIRMED,dao.observeEntryStatus("first-pending").first());dao.delete("first-pending");assertNull(dao.observeEntryStatus("first-pending").first())}finally{db.close()}}
 @Test fun eraseAllIsAtomicAndRestoresDefaults()=runTest {val context=ApplicationProvider.getApplicationContext<Context>();val db=Room.inMemoryDatabaseBuilder(context,LedgerDb::class.java).build();try{val repo=Repository(db);repo.seed();repo.dao.saveWallet(Wallet("custom-wallet"));repo.dao.save(Entry(id="erase-test",amount=100));repo.dao.evidence(ReceiptEvidence("erase-test","digest","transaction","name",0,"a".repeat(64)+".img"));db.openHelper.writableDatabase.execSQL("CREATE TRIGGER abort_erase BEFORE DELETE ON wallets BEGIN SELECT RAISE(ABORT, 'synthetic erase failure'); END");var failed=false;try{repo.clearUserData()}catch(_:android.database.sqlite.SQLiteException){failed=true};assertTrue(failed);assertNotNull(repo.dao.get("erase-test"));assertEquals(1,repo.dao.allEvidence().size);db.openHelper.writableDatabase.execSQL("DROP TRIGGER abort_erase");assertEquals(listOf("a".repeat(64)+".img"),repo.clearUserData());assertTrue(repo.dao.all().isEmpty());assertTrue(repo.dao.allEvidence().isEmpty());assertEquals(setOf("Tiền mặt","Ngân hàng"),repo.dao.wallets().first().map{it.name}.toSet())}finally{db.close()}}
}
